window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dfca6bb330278c13"]={"versions": [{"id": "FIG-dfca6bb330278c13", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 6). Die Funktion ist Teil der sicherheitsrelevanten E2E-Kommunikationsabsicherung (Senderseite) zur Erkennung von Übertragungsfehlern in Datenpaketen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Einstiegspunkt: Aufruf <code>E2E_P06Protect(Config, State, Data, Length)</code> mit Konfigurationszeiger <code>Config</code>, Zustandsstruktur <code>State</code>, Nutzdaten-Array/Buffer <code>Data</code> und Längenangabe <code>Length</code>.\n</li><li>Aktionen / Sub-Aktivitäten (mit Verfeinerungssymbol):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li>Verzweigungsbedingungen (Guards): <code>[wrong input]</code>, <code>[input ok]</code> sowie unbeschrifteter bzw. impliziter Pfad für ungültige Null-Zeiger.\n</li><li>Rückgabewerte / Endknoten: <code>return E2E_E_INPUTERR_NULL</code>, <code>return E2E_E_OK</code>, <code>return E2E_E_INPUTERR_WRONG</code> (am rechten Endknoten angeschnitten).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start bei Aufruf von <code>E2E_P06Protect(Config, State, Data, Length)</code>.\n</li><li>Ausführung der Eingangsvalidierung <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand des Validierungsergebnisses:\n<ul class=\"fig-list\"><li>Bei Null-Zeiger-Fehler: Übergang zum linken Endknoten mit Rückgabe <code>return E2E_E_INPUTERR_NULL</code>.\n</li><li>Bei sonstigen unzulässigen Eingabeparametern (<code>[wrong input]</code>): Übergang zum rechten Endknoten mit Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.\n</li><li>Bei erfolgreicher Validierung (<code>[input ok]</code>): Sequenzielle Ausführung der Profil-6-Schutzschritte:\n a) <code>Compute offset</code> (Berechnung des Offsets für die Header-Felder).\n b) <code>Write Length</code> (Schreiben der Gesamtlänge in das Datenfeld).\n c) <code>Write Counter</code> (Eintragen des aktuellen Zählerwerts).\n d) <code>Compute CRC</code> (Berechnung der Prüfsumme über Daten und Profil-6-Metadaten).\n e) <code>Write CRC</code> (Eintragen der berechneten CRC in das Datenfeld).\n f) <code>Increment Counter</code> (Inkrementieren des Sequenzzählers im Zustand <code>State</code>).\n g) Reguläres Funktionsende am mittleren Endknoten mit <code>return E2E_E_OK</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Ablaufdefinition für Implementierungen von E2E Profile 6 Protect gemäß Anforderung <code>[PRS_E2E_00423]</code>. Die Reihenfolge von Offset-Berechnung, Längeneintrag, Zählereintrag, CRC-Berechnung und anschließender Zählerinkrementierung muss exakt eingehalten werden, um protokollkonforme E2E-Header zu erzeugen. Vor jeder Datenmanipulation ist die Validierung der Zeiger und Werte durchzuführen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9a0b0cfeb1a440a7", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 6). Die Funktion ist Teil der sicherheitsrelevanten E2E-Kommunikationsabsicherung (Senderseite) zur Erkennung von Übertragungsfehlern in Datenpaketen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Einstiegspunkt: Aufruf <code>E2E_P06Protect(Config, State, Data, Length)</code>.\n</li><li>Aktionen / Sub-Aktivitäten (mit Verfeinerungssymbol):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li>Verzweigungsbedingungen (Guards): <code>[null input]</code>, <code>[input ok]</code>, <code>[wrong input]</code>.\n</li><li>Endknoten: Drei Aktivitätsendknoten mit Rückgabe (<code>return</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start bei Aufruf von <code>E2E_P06Protect(Config, State, Data, Length)</code>.\n</li><li>Ausführung der Eingangsvalidierung <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand des Validierungsergebnisses:\n<ul class=\"fig-list\"><li>Bei fehlenden Parametern (<code>[null input]</code>): Übergang zum linken Endknoten mit Rückgabe (<code>return</code>).\n</li><li>Bei ungültigen Parameterwerten (<code>[wrong input]</code>): Übergang zum rechten Endknoten mit Rückgabe (<code>return</code>).\n</li><li>Bei erfolgreicher Validierung (<code>[input ok]</code>): Sequenzielle Abarbeitung:\n a) <code>Compute offset</code>\n b) <code>Write Length</code>\n c) <code>Write Counter</code>\n d) <code>Compute CRC</code>\n e) <code>Write CRC</code>\n f) <code>Increment Counter</code>\n g) Übergang zum mittleren Endknoten mit Rückgabe (<code>return</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Ablaufdefinition für Implementierungen von E2E Profile 6 Protect gemäß Anforderung <code>[PRS_E2E_00423]</code>. Die Reihenfolge von Offset-Berechnung, Längeneintrag, Zählereintrag, CRC-Berechnung und anschließender Zählerinkrementierung muss exakt eingehalten werden, um protokollkonforme E2E-Header zu erzeugen. Vor jeder Datenmanipulation ist die Validierung der Zeiger und Werte durchzuführen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7a02effd8b9834bf", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 6). Die Funktion ist Teil der sicherheitsrelevanten E2E-Kommunikationsabsicherung (Senderseite) zur Erkennung von Übertragungsfehlern in Datenpaketen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Einstiegspunkt: Aufruf <code>E2E_P06Protect(Config, State, Data, Length)</code>.\n</li><li>Aktionen / Sub-Aktivitäten (mit Verfeinerungssymbol):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li>Verzweigungsbedingungen (Guards): <code>[null input]</code>, <code>[input ok]</code>, <code>[wrong input]</code>.\n</li><li>Endknoten: Drei Aktivitätsendknoten mit Rückgabe (<code>return</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start bei Aufruf von <code>E2E_P06Protect(Config, State, Data, Length)</code>.\n</li><li>Ausführung der Eingangsvalidierung <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand des Validierungsergebnisses:\n<ul class=\"fig-list\"><li>Bei fehlenden Parametern (<code>[null input]</code>): Übergang zum linken Endknoten mit Rückgabe (<code>return</code>).\n</li><li>Bei ungültigen Parameterwerten (<code>[wrong input]</code>): Übergang zum rechten Endknoten mit Rückgabe (<code>return</code>).\n</li><li>Bei erfolgreicher Validierung (<code>[input ok]</code>): Sequenzielle Abarbeitung:\n a) <code>Compute offset</code>\n b) <code>Write Length</code>\n c) <code>Write Counter</code>\n d) <code>Compute CRC</code>\n e) <code>Write CRC</code>\n f) <code>Increment Counter</code>\n g) Übergang zum mittleren Endknoten mit Rückgabe (<code>return</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Ablaufdefinition für Implementierungen von E2E Profile 6 Protect gemäß Anforderung <code>[PRS_E2E_00423]</code>. Die Reihenfolge von Offset-Berechnung, Längeneintrag, Zählereintrag, CRC-Berechnung und anschließender Zählerinkrementierung muss exakt eingehalten werden, um protokollkonforme E2E-Header zu erzeugen. Vor jeder Datenmanipulation ist die Validierung der Zeiger und Werte durchzuführen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-73eca9d88e96efc8", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 6). Die Funktion ist Teil der sicherheitsrelevanten E2E-Kommunikationsabsicherung (Senderseite) zur Erkennung von Übertragungsfehlern in Datenpaketen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Einstiegspunkt: Aufruf <code>E2E_P06Protect(Config, State, Data, Length)</code>.\n</li><li>Aktionen / Sub-Aktivitäten (mit Verfeinerungssymbol):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li>Verzweigungsbedingungen (Guards): <code>[null input]</code>, <code>[input ok]</code>, <code>[wrong input]</code>.\n</li><li>Endknoten: Drei Aktivitätsendknoten mit Rückgabe (<code>return</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start bei Aufruf von <code>E2E_P06Protect(Config, State, Data, Length)</code>.\n</li><li>Ausführung der Eingangsvalidierung <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand des Validierungsergebnisses:\n<ul class=\"fig-list\"><li>Bei fehlenden Parametern (<code>[null input]</code>): Übergang zum linken Endknoten mit Rückgabe (<code>return</code>).\n</li><li>Bei ungültigen Parameterwerten (<code>[wrong input]</code>): Übergang zum rechten Endknoten mit Rückgabe (<code>return</code>).\n</li><li>Bei erfolgreicher Validierung (<code>[input ok]</code>): Sequenzielle Abarbeitung:\n a) <code>Compute offset</code>\n b) <code>Write Length</code>\n c) <code>Write Counter</code>\n d) <code>Compute CRC</code>\n e) <code>Write CRC</code>\n f) <code>Increment Counter</code>\n g) Übergang zum mittleren Endknoten mit Rückgabe (<code>return</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Ablaufdefinition für Implementierungen von E2E Profile 6 Protect gemäß Anforderung <code>[PRS_E2E_00423]</code>. Die Reihenfolge von Offset-Berechnung, Längeneintrag, Zählereintrag, CRC-Berechnung und anschließender Zählerinkrementierung muss exakt eingehalten werden, um protokollkonforme E2E-Header zu erzeugen. Vor jeder Datenmanipulation ist die Validierung der Zeiger und Werte durchzuführen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-dfca6bb330278c13", "to": "FIG-9a0b0cfeb1a440a7", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung des linken Kontrollflusses von <code>Verify inputs of the protect function</code> um die Guard-Bedingung <code>[null input]</code> ergänzt.\n</li><li>Text der Rückgabewerte an den Endknoten unten abgeschnitten bzw. verkürzt auf <code>return</code> (Layout-/Beschnittänderung des Diagramms).\n</li><li>Signaturbeschriftung am Startknoten oben leicht beschnitten (<code>E2E_P06Protect(Config, State, Data, Length)</code>).\n</li></ul>"}, {"from": "FIG-9a0b0cfeb1a440a7", "to": "FIG-7a02effd8b9834bf", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7a02effd8b9834bf", "to": "FIG-73eca9d88e96efc8", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
